package io.github.hoangtnedu.java.warehouse;
import io.github.hoangtnedu.java.orders.*;import java.sql.*;import java.util.*;
public class WarehouseService {
 public void move(Database.User user,long id,String target)throws SQLException{if(!"WAREHOUSE".equals(user.role()))throw new IllegalArgumentException("Warehouse role required");try(var c=Database.open()){c.setAutoCommit(false);try{String state;int version;try(var p=c.prepareStatement("SELECT status,version FROM orders WHERE id=? FOR UPDATE")){p.setLong(1,id);try(var r=p.executeQuery()){if(!r.next())throw new SQLException("Missing order");state=r.getString(1);version=r.getInt(2);}}if(!(state.equals("PENDING")&&target.equals("PROCESSING")||state.equals("PROCESSING")&&target.equals("READY")))throw new SQLException("Wrong state");
 if(target.equals("PROCESSING")){try(var p=c.prepareStatement("SELECT product_id,quantity FROM order_items WHERE order_id=? ORDER BY product_id")){p.setLong(1,id);try(var r=p.executeQuery()){while(r.next()){try(var stock=c.prepareStatement("UPDATE products SET stock=stock-?,version=version+1 WHERE id=? AND stock>=?")){stock.setInt(1,r.getInt(2));stock.setLong(2,r.getLong(1));stock.setInt(3,r.getInt(2));if(stock.executeUpdate()!=1)throw new SQLException("Insufficient stock");}}}}}
 try(var p=c.prepareStatement("UPDATE orders SET status=?,version=version+1 WHERE id=? AND version=?")){p.setString(1,target);p.setLong(2,id);p.setInt(3,version);if(p.executeUpdate()!=1)throw new SQLException("Conflict");}Database.history(c,id,state,target,user.id(),"SWING");c.commit();}catch(Exception e){c.rollback();if(e instanceof SQLException x)throw x;throw new SQLException(e);}}}
 public List<Object[]> pending()throws SQLException{try(var c=Database.open();var p=c.prepareStatement("SELECT id,status,version FROM orders WHERE status IN ('PENDING','PROCESSING') ORDER BY id");var r=p.executeQuery()){List<Object[]> rows=new ArrayList<>();while(r.next())rows.add(new Object[]{r.getLong(1),r.getString(2),r.getInt(3)});return rows;}}
}